// menu preso no alto: leva a cada grupo e mostra em qual você está
let grupoAtual = null, rafPular = 0;
function renderPular(grupos) {
  const nav = document.getElementById("pular");
  nav.hidden = !grupos.length;
  document.getElementById("pular-trilho").innerHTML = '<button type="button" class="pular-chip" data-pular="topo">↑ Topo</button>' +
    '<button type="button" class="pular-chip" data-pular="pl-painel">🎵 Playlists</button>' +
    grupos.map(function (x) {
      return '<button type="button" class="pular-chip' + (x.cls ? " " + x.cls : "") + '" data-pular="' + x.id + '">' + x.ico + esc(x.label) +
        ' <span class="n">' + x.n + "</span></button>";
    }).join("");
  document.documentElement.style.setProperty("--pular-h", nav.offsetHeight + "px");
  grupoAtual = undefined;
  marcarGrupo();
}
function marcarGrupo() {
  const nav = document.getElementById("pular");
  if (nav.hidden) return;
  const limite = nav.getBoundingClientRect().bottom + Math.min(window.innerHeight * 0.3, 240);
  let id = null;
  document.querySelectorAll("#lista-jogos .group").forEach(function (s) {
    if (s.getBoundingClientRect().top <= limite) id = s.id;
  });
  if (id === grupoAtual) return;
  grupoAtual = id;
  const trilho = document.getElementById("pular-trilho");
  trilho.querySelectorAll("[data-pular]").forEach(function (b) {
    const on = b.dataset.pular === id;
    if (on) b.setAttribute("aria-current", "true"); else b.removeAttribute("aria-current");
    if (on && (b.offsetLeft < trilho.scrollLeft || b.offsetLeft + b.offsetWidth > trilho.scrollLeft + trilho.clientWidth)) {
      trilho.scrollLeft = Math.max(0, b.offsetLeft - 48);
    }
  });
}
window.addEventListener("scroll", function () {
  if (rafPular) return;
  rafPular = requestAnimationFrame(function () { rafPular = 0; marcarGrupo(); });
}, {passive: true});
window.addEventListener("resize", function () {
  document.documentElement.style.setProperty("--pular-h", document.getElementById("pular").offsetHeight + "px");
  grupoAtual = undefined;
  marcarGrupo();
});
