// fotos ao segurar a capa (toque) ou deixar o mouse em cima
let prev = null;
function previaPara(fim) {
  if (!prev) return;
  clearTimeout(prev.t0); clearInterval(prev.ti);
  const cov = prev.el.querySelector(".cover");
  if (cov) cov.querySelectorAll(".previa, .previa-barra").forEach(function (x) { x.remove(); });
  if (fim && prev.ativa && (prev.visto || !prev.el.classList.contains("vit-item"))) { prev.engolir = true; const p = prev; setTimeout(function () { if (prev === p) prev = null; }, 400); }
  else prev = null;
}
function previaComeca(el, atraso) {
  previaPara(false);
  const fotosG = (FICHA[el.dataset.previa] || {}).sh || [];
  if (!fotosG.length) return;
  prev = {el: el, ativa: false};
  prev.t0 = setTimeout(function () {
    const cov = el.querySelector(".cover");
    if (!cov || !prev || prev.el !== el) return;
    prev.ativa = true;
    let i = 0;
    const im = document.createElement("img");
    im.className = "previa"; im.alt = ""; im.referrerPolicy = "no-referrer"; im.src = fotoURL(fotosG[0]);
    im.addEventListener("load", function () { if (prev && prev.el === el) prev.visto = true; });
    const bar = document.createElement("span"); bar.className = "previa-barra"; bar.style.width = (100 / fotosG.length) + "%";
    cov.appendChild(im); cov.appendChild(bar);
    prev.ti = setInterval(function () {
      i = (i + 1) % fotosG.length;
      im.src = fotoURL(fotosG[i]); bar.style.width = ((i + 1) * 100 / fotosG.length) + "%";
    }, 1100);
  }, atraso);
}
document.addEventListener("pointerover", function (e) {
  if (e.pointerType !== "mouse") return;
  const el = e.target.closest ? e.target.closest("[data-previa]") : null;
  if (el && (!prev || prev.el !== el)) previaComeca(el, 450);
});
document.addEventListener("pointerout", function (e) {
  if (!prev || e.pointerType !== "mouse") return;
  if (!prev.el.contains(e.relatedTarget)) previaPara(false);
});
document.addEventListener("pointerdown", function (e) {
  if (e.pointerType === "mouse") return;
  const el = e.target.closest ? e.target.closest("[data-previa]") : null;
  if (el && !e.target.closest(".ver, .fav, .pl-rapido")) previaComeca(el, 380);
});
["pointerup", "pointercancel"].forEach(function (ev) {
  document.addEventListener(ev, function (e) { if (e.pointerType !== "mouse" && prev) previaPara(true); });
});
document.addEventListener("contextmenu", function (e) { if (prev && prev.ativa) e.preventDefault(); });
document.addEventListener("click", function (e) {
  if (prev && prev.engolir) { e.preventDefault(); e.stopPropagation(); prev = null; }
}, true);
let capasOk = 0, capasErro = 0;
function avisoCapas() {
  const bloqueado = capasOk === 0 && capasErro >= 2;
  document.getElementById("aviso-capas").hidden = !bloqueado;
  document.getElementById("barra-aviso").hidden = !bloqueado;
}
document.addEventListener("load", function (e) {
  const t = e.target;
  if (t && t.tagName === "IMG" && t.classList.contains("capa")) { capasOk++; avisoCapas(); }
}, true);
document.addEventListener("error", function (e) {
  const t = e.target;
  if (t && t.tagName === "IMG" && t.classList.contains("capa")) { capasErro++; t.remove(); avisoCapas(); }
}, true);
function renderView() {
  document.querySelectorAll("#ver button").forEach(function (b) { b.setAttribute("aria-pressed", String(b.dataset.view === state.view)); });
  document.querySelectorAll("#agrupar button").forEach(function (b) { b.setAttribute("aria-pressed", String(b.dataset.agr === state.agrupar)); });
}
document.querySelectorAll("#agrupar button").forEach(function (b) {
  b.addEventListener("click", function () { state.agrupar = b.dataset.agr; save(); renderView(); renderList(); });
});
document.getElementById("so-interesse").addEventListener("change", function (e) { state.onlyFav = e.target.checked; renderList(); });
document.getElementById("romance").addEventListener("change", function (e) { state.rom = e.target.value; renderList(); });
document.getElementById("minha").addEventListener("change", function (e) { state.minha = e.target.value; renderList(); });
document.querySelectorAll("#ver button").forEach(function (b) {
  b.addEventListener("click", function () { state.view = b.dataset.view; save(); renderView(); renderList(); });
});
document.getElementById("genero").addEventListener("change", function (e) { state.genre = e.target.value; renderList(); });
document.getElementById("so-marcados").addEventListener("change", function (e) { state.onlyMarked = e.target.checked; renderList(); });
document.querySelectorAll(".seg button[data-cap]").forEach(function (b) {
  b.addEventListener("click", function () { state.cap = Number(b.dataset.cap); save(); renderMeter(); if (state.size === "cabe") renderList(); });
});
document.getElementById("btn-hype").addEventListener("click", function () { state.sel = hypeSet(); save(); renderMeter(); renderList(); });
document.getElementById("btn-all").addEventListener("click", function () {
  state.sel = new Set(DATA.filter(counted).map(function (g) { return g.id; }));
  save(); renderMeter(); renderList();
});
document.addEventListener("click", function (e) {
  if (!e.target.closest) return;
  if (e.target.closest("[data-semsel]")) { state.sel = new Set(); save(); renderMeter(); renderList(); return; }
  if (e.target.closest("[data-semfav]")) {
    if (!window.confirm("Tirar a estrela de todos os " + state.fav.size + " jogos?")) return;
    state.fav = new Set();
    document.querySelectorAll("[data-fav]").forEach(function (x) {
      x.setAttribute("aria-pressed", "false");
      x.textContent = x.classList.contains("fav-ficha") ? "☆ Tenho interesse" : "☆";
    });
    save(); renderMeter(); renderList(); return;
  }
  const pr = e.target.closest("[data-plrapido]");
  if (pr) {
    abrirFicha(pr.dataset.plrapido);
    setTimeout(function () { const p = document.querySelector(".ficha-pls"); if (p) p.scrollIntoView({block: "center", behavior: "smooth"}); }, 120);
  }
});
document.addEventListener("click", function (e) {
  const m = e.target.closest ? e.target.closest("[data-mais]") : null;
  if (m) {
    state.limS = state.limS || {};
    const k = m.dataset.mais, ant = state.limS[k] || PASSO, c = POUCOS[k], grade = m.previousElementSibling;
    state.limS[k] = ant + PASSO;
    if (!c || !grade) { renderList(); return; }
    grade.insertAdjacentHTML("beforeend", c.items.slice(ant, ant + PASSO).map(c.html).join(""));
    const resta = c.items.length - ant - PASSO;
    if (resta > 0) m.textContent = "Mostrar mais " + Math.min(resta, PASSO) + " (" + resta.toLocaleString("pt-BR") + " restantes)";
    else m.remove();
  }
});
document.getElementById("btn-none").addEventListener("click", function () { state.sel = new Set(); save(); renderMeter(); renderList(); });
document.querySelectorAll(".tile").forEach(function (t) {
  t.addEventListener("click", function () {
    state.status = state.status === t.dataset.status ? null : t.dataset.status;
    renderTiles(); renderList();
  });
});
document.getElementById("busca").addEventListener("input", function (e) { state.q = e.target.value; renderList(); });
document.getElementById("lista").addEventListener("change", function (e) { state.list = e.target.value; renderTiles(); renderList(); });
document.getElementById("ordem").addEventListener("change", function (e) { state.sort = e.target.value; renderList(); });
document.getElementById("so-destaque").addEventListener("change", function (e) { state.onlyHype = e.target.checked; renderList(); });

// ficha do jogo: resumo, fotos e links, num modal
const ficha = document.getElementById("ficha");
let fotos = [], fotoI = 0, fotoOk = 0, fotoErro = 0;
function abrirFicha(id) {
  const g = DATA.find(function (x) { return x.id === id; });
  if (!g || !ficha || typeof ficha.showModal !== "function") return;
  const f = FICHA[id] || {};
  fotos = f.sh || [];
  fotoI = 0; fotoOk = 0; fotoErro = 0;
  const st = STATUS[g.s];
  const isSel = state.sel.has(g.id);
  const pe = counted(g)
    ? '<label class="inst" for="f-' + g.id + '"><input type="checkbox" id="f-' + g.id + '" data-id="' + g.id + '"' + (isSel ? " checked" : "") + "> Marcar pra instalar</label>"
    : '<span class="out">' + (g.s === "veto" ? (g.x === "ms" ? "Fora da lista: romance só do mesmo sexo" : g.x === "ot" ? "Fora da lista: protagonista mulher que namora homens" : g.x === "s2" ? "Fora da lista: só roda no Switch 2" : g.o === "so" ? "Fora da lista: só funciona com internet" : "Fora da lista") : "Ainda não saiu no Switch") + "</span>";
  let galeria = "";
  if (fotos.length) {
    galeria = '<div class="ficha-galeria" role="group" aria-label="Fotos do jogo"><div class="ficha-palco">' +
      '<img class="ficha-foto" id="ficha-foto" src="' + esc(fotoURL(fotos[0])) + '" alt="Foto 1 de ' + fotos.length + ' do jogo" referrerpolicy="no-referrer">' +
      (fotos.length > 1 ? '<button type="button" class="ficha-seta ant" data-passo="-1" aria-label="Foto anterior">‹</button>' +
        '<button type="button" class="ficha-seta prox" data-passo="1" aria-label="Próxima foto">›</button>' : "") +
      '<span class="ficha-conta" id="ficha-conta">1 / ' + fotos.length + "</span></div>" +
      (fotos.length > 1 ? '<div class="ficha-mini">' + fotos.map(function (h, i) {
        return '<button type="button" class="mini' + (i ? "" : " on") + '" data-foto="' + i + '" aria-label="Foto ' + (i + 1) + '"' + (i ? "" : ' aria-current="true"') + ">" +
          '<img src="' + esc(fotoURL(h)) + '" alt="" referrerpolicy="no-referrer"></button>';
      }).join("") + "</div>" : "") + "</div>";
  }
  const e = ex(g), ik = idiomaKey(g);
  const dados = [];
  if (e.nt) dados.push((e.nt < 60 ? "👎 Nota baixa dos jogadores: " : "★ Nota dos jogadores: ") + e.nt + "/100");
  if (e.hl) dados.push("⏱ História: " + horas(e.hl) + (e.hx ? " · com extras: " + horas(e.hx) : ""));
  dados.push(ik === "dub" ? "🎙 Dublado em PT-BR" : ik === "leg" ? "💬 PT-BR oficial" : ik === "fa" ? "💬 Tradução de fã pronta" : ik === "minha" ? "✎ Sua tradução" : "Sem português ainda");
  if (ROM[g.rom] && (g.rom === "sim" || g.rom === "opc" || g.rom === "leve")) dados.push("♥ " + ROM[g.rom].label);
  if (ONDE[g.id]) dados.push("📦 " + ONDE[g.id]);
  const trailer = e.yt ? '<a class="ficha-trailer" href="https://www.youtube.com/watch?v=' + e.yt + '" target="_blank" rel="noopener" aria-label="Ver o trailer no YouTube">' +
    '<img src="https://i.ytimg.com/vi/' + e.yt + '/hqdefault.jpg" alt="" referrerpolicy="no-referrer" loading="lazy"><span class="play"><span>▶</span></span><span class="rot">Trailer no YouTube</span></a>' : "";
  const texto = (f.d ? "<h3>O que é</h3><p>" + esc(f.d) + "</p>" : "") +
    (g.t ? "<h3>" + (g.sg ? "Por que eu sugeri" : "Nota da lista") + "</h3><p>" + esc(g.t) + "</p>" : "");
  ficha.className = "s-" + g.s;
  ficha.innerHTML = '<div class="ficha-in">' +
    '<div class="ficha-topo">' + coverHTML(g) +
    '<div class="ficha-titulo"><span class="gen">' + GENRES[g.gn].label + '</span><h2 id="ficha-nome">' + esc(g.n) + "</h2>" +
    '<div class="card-top"><span class="pill">' + st.label + "</span>" + tagsHTML(g) + "</div></div>" +
    '<button type="button" class="ficha-x" data-fechar autofocus aria-label="Fechar">✕</button></div>' +
    '<div class="ficha-dados">' + dados.map(function (x) { return "<span>" + esc(x) + "</span>"; }).join("") + "</div>" +
    trailer + galeria +
    '<p class="ficha-sem" id="ficha-sem"' + (fotos.length ? " hidden>" : ">Ainda não tenho fotos deste jogo. Veja os vídeos no YouTube, no link abaixo.") + "</p>" +
    '<div class="ficha-texto">' + texto + "</div>" +
    '<div class="links"><a class="loja" href="' + videoURL(g) + '" target="_blank" rel="noopener">Ver vídeos no YouTube ↗</a>' +
    '<a class="loja" href="' + lojaURL(g) + '" target="_blank" rel="noopener">Ver preço ↗</a>' +
    (g.tr ? '<a class="loja" href="' + trURL(g) + '" target="_blank" rel="noopener">Ver a tradução ↗</a>' : "") + "</div>" +
    planosHTML(g) + fichaPlsHTML(g) +
    '<div class="ficha-pe"><span class="size">' + sizeTxt(g, "Sem tamanho") + "</span>" + hypeHTML(g) +
    '<button type="button" class="fav fav-ficha" data-fav="' + g.id + '" aria-pressed="' + state.fav.has(g.id) + '">' + (state.fav.has(g.id) ? "★ Tenho interesse" : "☆ Tenho interesse") + "</button>" + pe + mtSelect(g) + "</div>" +
    "</div>";
  ficha.showModal();
  ficha.scrollTop = 0;
}
function mostrarFoto(i) {
  if (!fotos.length) return;
  fotoI = (i + fotos.length) % fotos.length;
  const img = document.getElementById("ficha-foto");
  if (img) { img.src = fotoURL(fotos[fotoI]); img.alt = "Foto " + (fotoI + 1) + " de " + fotos.length + " do jogo"; }
  const conta = document.getElementById("ficha-conta");
  if (conta) conta.textContent = (fotoI + 1) + " / " + fotos.length;
  ficha.querySelectorAll(".mini").forEach(function (b, j) {
    b.classList.toggle("on", j === fotoI);
    if (j === fotoI) b.setAttribute("aria-current", "true"); else b.removeAttribute("aria-current");
  });
}
function avisoFotos() {
  if (fotoOk > 0 || fotoErro < Math.min(2, fotos.length)) return;
  const gal = ficha.querySelector(".ficha-galeria");
  if (gal) gal.hidden = true;
  const sem = document.getElementById("ficha-sem");
  if (sem) {
    sem.textContent = "As fotos não carregaram aqui. Isso acontece quando a página abre dentro do app do Claude, que bloqueia imagens de fora, ou sem internet. Abra o arquivo no Chrome, ou veja os vídeos no YouTube, no link abaixo.";
    sem.hidden = false;
  }
}
document.addEventListener("click", function (e) {
  const b = e.target.closest ? e.target.closest("[data-ver]") : null;
  if (b) abrirFicha(b.dataset.ver);
});
if (ficha) {
  ficha.addEventListener("click", function (e) {
    if (e.target === ficha) { ficha.close(); return; }
    const t = e.target.closest("[data-fechar], [data-passo], [data-foto]");
    if (!t) return;
    if (t.hasAttribute("data-fechar")) ficha.close();
    else if (t.dataset.passo) mostrarFoto(fotoI + Number(t.dataset.passo));
    else mostrarFoto(Number(t.dataset.foto));
  });
  ficha.addEventListener("keydown", function (e) {
    if (e.target.tagName === "INPUT" || e.target.tagName === "SELECT") return;
    if (e.key === "ArrowRight") { mostrarFoto(fotoI + 1); e.preventDefault(); }
    else if (e.key === "ArrowLeft") { mostrarFoto(fotoI - 1); e.preventDefault(); }
  });
  ficha.addEventListener("load", function (e) {
    if (e.target.tagName === "IMG" && !e.target.classList.contains("capa")) { fotoOk++; avisoFotos(); }
  }, true);
  ficha.addEventListener("error", function (e) {
    if (e.target.tagName === "IMG" && !e.target.classList.contains("capa")) { fotoErro++; avisoFotos(); }
  }, true);
  ficha.addEventListener("close", function () { ficha.innerHTML = ""; fotos = []; });
}

load();
refazOrdemNome();
(function () {
  let ok = true;
  try { localStorage.setItem(KEY + "-teste", "1"); ok = localStorage.getItem(KEY + "-teste") === "1"; localStorage.removeItem(KEY + "-teste"); } catch (e) { ok = false; }
  if (!ok) document.getElementById("aviso-salvar").hidden = false;
})();
